import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { CONFIG } from './config.js';

const supabase = createClient(CONFIG.SUPABASE_URL, CONFIG.SUPABASE_PUBLISHABLE_KEY, {
  auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true, flowType: 'pkce' }
});
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cents=v=>Math.round(Number(v||0)*100);
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(n||0)/100);
const dateOnly=v=>v?new Date(`${v}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'No deadline';
const relativeDate=v=>{if(!v)return'No deadline';const d=Math.ceil((new Date(`${v}T23:59:59`)-new Date())/86400000);return d<0?`${Math.abs(d)}d overdue`:d===0?'Due today':`${d}d remaining`};
const uid=()=>state.session?.user?.id;
const state={session:null,profile:null,funds:[],homeCommitments:[],fund:null,members:[],commitments:[],plans:[],allocations:[],calls:[],shares:[],settlements:[],events:[],channel:null,refreshTimer:null};

const icons={
  plus:'<svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg>',
  arrow:'<svg viewBox="0 0 24 24"><path d="M19 12H5m6-6-6 6 6 6"/></svg>',
  users:'<svg viewBox="0 0 24 24"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm13 10v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/></svg>',
  target:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/></svg>',
  promise:'<svg viewBox="0 0 24 24"><path d="M8 12.5 10.5 15 16 9.5"/><path d="M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20Z"/></svg>',
  plan:'<svg viewBox="0 0 24 24"><path d="M8 3h8M9 3v3h6V3M6 5h12a2 2 0 0 1 2 2v14H4V7a2 2 0 0 1 2-2Z"/><path d="M8 11h8M8 15h5"/></svg>',
  call:'<svg viewBox="0 0 24 24"><path d="M3 12h18M15 6l6 6-6 6"/><circle cx="6" cy="12" r="3"/></svg>',
  settle:'<svg viewBox="0 0 24 24"><path d="M7 7h11l-3-3M17 17H6l3 3"/></svg>',
  shield:'<svg viewBox="0 0 24 24"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/></svg>',
  repeat:'<svg viewBox="0 0 24 24"><path d="M17 2l4 4-4 4M3 11V9a3 3 0 0 1 3-3h15M7 22l-4-4 4-4m14-1v2a3 3 0 0 1-3 3H3"/></svg>',
  check:'<svg viewBox="0 0 24 24"><path d="m5 12 4 4L19 6"/></svg>',
  clock:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>',
  more:'<svg viewBox="0 0 24 24"><circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/></svg>',
  trash:'<svg viewBox="0 0 24 24"><path d="M4 7h16M9 7V4h6v3m-8 0 1 14h8l1-14M10 11v6m4-6v6"/></svg>',
  edit:'<svg viewBox="0 0 24 24"><path d="M12 20h9M16.5 3.5a2.12 2.12 0 0 1 3 3L8 18l-4 1 1-4Z"/></svg>'
};
const icon=n=>icons[n]||'';

function toast(message,type='info'){const e=document.createElement('div');e.className=`toast ${type}`;e.textContent=message;document.body.append(e);requestAnimationFrame(()=>e.classList.add('show'));setTimeout(()=>{e.classList.remove('show');setTimeout(()=>e.remove(),200)},3200)}
function busy(btn,on,label='Working…'){if(!btn)return;if(on){btn.dataset.old=btn.innerHTML;btn.disabled=true;btn.innerHTML=`<span class="spinner"></span>${esc(label)}`}else{btn.disabled=false;btn.innerHTML=btn.dataset.old||btn.innerHTML}}
function modal(html,wide=false){closeModal();const b=document.createElement('div');b.className='sheetBack';b.id='sheetBack';b.innerHTML=`<section class="sheet ${wide?'wide':''}" role="dialog" aria-modal="true"><div class="grab"></div>${html}</section>`;document.body.append(b);b.onclick=e=>{if(e.target===b||e.target.closest('[data-close]'))closeModal()};requestAnimationFrame(()=>b.classList.add('open'))}
function closeModal(){const b=$('#sheetBack');if(!b)return;b.classList.remove('open');setTimeout(()=>b.remove(),160)}
function renderSplash(){$('#app').innerHTML='<main class="splash"><div class="mark">S</div><span class="spinner lg"></span></main>'}

async function init(){renderSplash();const {data:{session},error}=await supabase.auth.getSession();if(error)console.error('Session restore failed',error);state.session=session;supabase.auth.onAuthStateChange(async(event,s)=>{state.session=s;if(event==='INITIAL_SESSION')return;if(!s){reset();renderLanding()}else await boot()});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(error=>console.warn('Service worker registration failed',error));await boot()}
function reset(){unsubscribe();Object.assign(state,{profile:null,funds:[],homeCommitments:[],fund:null,members:[],commitments:[],plans:[],allocations:[],calls:[],shares:[],settlements:[],events:[]})}
async function boot(){if(!state.session)return renderLanding();try{await ensureProfile();await loadFunds();renderHome()}catch(e){console.error(e);toast(e.message||'Could not load Save','error');renderHome(true)}}
async function ensureProfile(){const u=state.session.user,m=u.user_metadata||{};const payload={id:u.id,display_name:m.full_name||m.name||'Saver',avatar_url:m.avatar_url||m.picture||null,updated_at:new Date().toISOString()};const {data,error}=await supabase.from('profiles').upsert(payload,{onConflict:'id'}).select().single();if(error)throw error;state.profile=data}
async function loadFunds(){const {data,error}=await supabase.from('funds').select('*, fund_members!inner(user_id,status,role)').eq('fund_members.user_id',uid()).eq('fund_members.status','active').order('created_at',{ascending:false});if(error)throw error;state.funds=data||[];const ids=state.funds.map(f=>f.id);state.homeCommitments=[];if(ids.length){const q=await supabase.from('commitments').select('fund_id,user_id,amount_cents,strength').in('fund_id',ids).neq('status','cancelled');if(q.error)throw q.error;state.homeCommitments=q.data||[]}}

function renderLanding(){$('#app').innerHTML=`<main class="landing"><nav class="landingNav"><div class="brand"><span class="mark sm">S</span><div><strong>Save</strong><small>Commit together.</small></div></div><span class="modeBadge">No money held</span></nav><section class="landingHero"><div class="heroCopy"><span class="eyebrow">Trips · tickets · events · groups</span><h1>Make the promise<br><em>before the purchase.</em></h1><p>Save helps groups commit what they can contribute, reserve those promises for plans, request reimbursement when it matters, and settle up clearly afterward. Your money never sits with Save.</p><button class="googleButton" id="googleLogin"><span class="googleG">G</span>Continue with Google</button><div class="trustLine">${icon('shield')}<span>Planning and accountability only · no bank account required</span></div></div><div class="heroVisual"><div class="promisePreview"><span class="previewLabel">MIAMI 2027</span><strong>$4,650 <small>committed</small></strong><div class="progress xl"><span style="width:78%"></span></div><div class="previewGoal"><span>$6,000 goal</span><b>$1,350 to go</b></div><div class="previewPeople"><div><i>B</i><span>Brian</span><b>$1,200 firm</b></div><div><i>A</i><span>Ashley</span><b>$950 firm</b></div><div><i>M</i><span>Mike</span><b>$800 flexible</b></div></div><div class="previewCall"><span>${icon('call')}</span><div><b>Hotel deposit due</b><small>Your share: $240 by Sep 12</small></div><em>Open</em></div></div></div></section><footer class="landingFoot">Plan together. Commit together. Pay when it matters.</footer></main>`;$('#googleLogin').onclick=googleLogin}
async function googleLogin(){const b=$('#googleLogin');busy(b,true,'Opening Google…');const {error}=await supabase.auth.signInWithOAuth({provider:'google',options:{redirectTo:CONFIG.APP_URL,queryParams:{prompt:'select_account'}}});if(error){busy(b,false);toast(error.message,'error')}}

function accountChip(){const a=state.profile?.avatar_url,n=state.profile?.display_name||'Saver';return `<button class="accountChip" id="accountMenu">${a?`<img src="${esc(a)}" alt="">`:`<span>${esc(n[0])}</span>`}<b>${esc(n.split(' ')[0])}</b></button>`}
function shell(content,active='goals'){return `<main class="appShell"><header class="appHeader"><button class="brand homeBrand" id="homeLogo"><span class="mark sm">S</span><div><strong>Save</strong><small>Commitment planner</small></div></button>${accountChip()}</header>${content}<nav class="mobileNav"><button data-home class="${active==='goals'?'active':''}">${icon('target')}<span>Goals</span></button><button data-new>${icon('plus')}<span>New</span></button><button data-how class="${active==='how'?'active':''}">${icon('promise')}<span>How it works</span></button></nav></main>`}
function bindShell(){$('#homeLogo')?.addEventListener('click',goHome);$$('[data-home]').forEach(b=>b.onclick=goHome);$$('[data-new]').forEach(b=>b.onclick=showCreateGoal);$$('[data-how]').forEach(b=>b.onclick=showHow);$('#accountMenu')?.addEventListener('click',showAccount)}
async function goHome(){unsubscribe();state.fund=null;await loadFunds();renderHome()}

function fundTotals(fundId){const c=state.homeCommitments.filter(x=>x.fund_id===fundId);return {total:c.reduce((s,x)=>s+Number(x.amount_cents||0),0),firm:c.filter(x=>x.strength==='firm').reduce((s,x)=>s+Number(x.amount_cents||0),0),count:c.length}}
function renderHome(error=false){const all=state.homeCommitments.reduce((s,c)=>s+Number(c.amount_cents||0),0);const content=`<section class="homeHero"><div><span class="eyebrow">Your commitments</span><h1>${money(all)}</h1><p>${state.funds.length?`Promised across ${state.funds.length} active ${state.funds.length===1?'goal':'goals'}. No money has moved.`:'Create a goal and invite the people planning it with you.'}</p></div><div class="heroActions"><button class="button secondary" id="joinGoal">Join with code</button><button class="button primary" id="newGoal">${icon('plus')} New goal</button></div></section>${error?'<div class="inlineAlert error">Some collaborative data could not be refreshed.</div>':''}<section class="section"><div class="sectionTitle"><div><span class="eyebrow">Shared plans</span><h2>Goals</h2></div><span class="quietPill">Promises, not deposits</span></div><div class="goalGrid">${state.funds.length?state.funds.map(goalCard).join(''):`<button class="emptyGoal" id="emptyNew"><span>${icon('target')}</span><strong>Create your first shared goal</strong><small>Set a target, make your commitment, invite your group, and start planning.</small></button>`}</div></section><section class="principleStrip"><span>${icon('shield')}</span><div><strong>Save never holds the group's money.</strong><p>A commitment is a planning promise. People keep their money wherever they already keep it and pay using the method they choose when a real expense is due.</p></div></section>`;$('#app').innerHTML=shell(content);bindShell();$('#joinGoal')?.addEventListener('click',showJoin);$('#newGoal')?.addEventListener('click',showCreateGoal);$('#emptyNew')?.addEventListener('click',showCreateGoal);$$('[data-goal]').forEach(x=>x.onclick=()=>openGoal(x.dataset.goal))}
function goalCard(f){const t=fundTotals(f.id),pct=Math.min(100,Math.round(t.total/Math.max(1,Number(f.goal_cents))*100)),gap=Math.max(0,Number(f.goal_cents)-t.total);return `<button class="goalCard" data-goal="${f.id}"><div class="goalTop"><span class="goalEmoji">${esc(f.emoji||'✦')}</span><span class="goalDate">${relativeDate(f.goal_date)}</span></div><div><span class="eyebrow">${esc(f.category||'Goal')}</span><h3>${esc(f.name)}</h3></div><div class="commitFigure"><strong>${money(t.total)}</strong><span>committed of ${money(f.goal_cents)}</span></div><div class="progress"><span style="width:${pct}%"></span></div><div class="goalFoot"><span>${pct}% funded by promises</span><b>${gap?`${money(gap)} gap`:'Goal covered'}</b></div></button>`}

async function openGoal(id){renderSplash();const qs=await Promise.all([
 supabase.from('funds').select('*').eq('id',id).single(),
 supabase.from('fund_members').select('*,profiles(display_name,avatar_url)').eq('fund_id',id).eq('status','active').order('joined_at'),
 supabase.from('commitments').select('*').eq('fund_id',id).neq('status','cancelled'),
 supabase.from('planned_expenses').select('*').eq('fund_id',id).neq('status','cancelled').order('due_date',{ascending:true,nullsFirst:false}),
 supabase.from('plan_allocations').select('*').eq('fund_id',id),
 supabase.from('funding_calls').select('*').eq('fund_id',id).neq('status','cancelled').order('created_at',{ascending:false}),
 supabase.from('funding_call_shares').select('*').eq('fund_id',id),
 supabase.from('settlements').select('*').eq('fund_id',id).order('created_at',{ascending:false}),
 supabase.from('commitment_events').select('*').eq('fund_id',id).order('created_at',{ascending:false}).limit(30)
]);
 const err=qs.find(q=>q.error)?.error;if(err){toast(err.message,'error');return goHome()}
 [state.fund,state.members,state.commitments,state.plans,state.allocations,state.calls,state.shares,state.settlements,state.events]=qs.map(q=>q.data);renderGoal();subscribe(id)}
function memberName(id){return state.members.find(m=>m.user_id===id)?.profiles?.display_name||'Member'}
function memberAvatar(m){const p=m.profiles||{},n=p.display_name||'M';return p.avatar_url?`<img src="${esc(p.avatar_url)}" alt="">`:`<span>${esc(n[0])}</span>`}
function commitmentFor(id){return state.commitments.find(c=>c.user_id===id)||{amount_cents:0,strength:'firm'}}
function allocatedFor(id){const active=new Set(state.plans.filter(p=>['planned','ready'].includes(p.status)).map(p=>p.id));return state.allocations.filter(a=>a.user_id===id&&active.has(a.plan_id)).reduce((n,a)=>n+Number(a.amount_cents||0),0)}
function calledFor(id){return state.shares.reduce((s,a)=>s+(a.user_id===id?Number(a.amount_cents):0),0)}
function fulfilledFor(id){return state.shares.reduce((s,a)=>s+(a.user_id===id&&a.status==='covered'?Number(a.amount_cents):0),0)}
function goalStats(){const total=state.commitments.reduce((s,c)=>s+Number(c.amount_cents),0),firm=state.commitments.filter(c=>c.strength==='firm').reduce((s,c)=>s+Number(c.amount_cents),0),planned=state.plans.filter(p=>p.status!=='paid').reduce((s,p)=>s+Number(p.budget_cents),0),actual=state.plans.filter(p=>p.status==='paid').reduce((s,p)=>s+Number(p.actual_cents||p.budget_cents),0),claimed=state.plans.filter(p=>p.status!=='paid'&&p.allocation_mode!=='unassigned').reduce((s,p)=>s+Number(p.budget_cents),0);return{total,firm,planned,actual,claimed,gap:Math.max(0,Number(state.fund.goal_cents)-total),planGap:Math.max(0,Number(state.fund.goal_cents)-planned)}}
function renderGoal(){const f=state.fund,mine=commitmentFor(uid()),s=goalStats(),pct=Math.min(100,Math.round(s.total/Math.max(1,Number(f.goal_cents))*100)),plannedPct=Math.min(100,Math.round(s.planned/Math.max(1,Number(f.goal_cents))*100)),myAlloc=allocatedFor(uid()),remaining=Math.max(0,Number(mine.amount_cents)-myAlloc),myPending=state.shares.filter(x=>x.user_id===uid()&&x.status==='pending').reduce((n,x)=>n+Number(x.amount_cents),0);const content=`<button class="backButton" id="backHome">${icon('arrow')} All goals</button><section class="goalHero"><div class="goalIdentity"><span class="goalEmoji lg">${esc(f.emoji||'✦')}</span><div><span class="eyebrow">${esc(f.category)}</span><h1>${esc(f.name)}</h1><p>${f.description?esc(f.description)+' · ':''}${dateOnly(f.goal_date)} · ${state.members.length} ${state.members.length===1?'person':'people'}</p></div></div><div class="heroTools"><button class="button secondary compactBtn" id="editGoal">${icon('edit')} Edit goal</button><button class="iconAction" id="invite" aria-label="Invite members">${icon('users')}</button><button class="iconAction" id="goalSettings" aria-label="Goal settings">${icon('more')}</button></div></section><section class="goalOverview"><div class="goalNumber"><span>Goal</span><strong>${money(f.goal_cents)}</strong><small>${f.goal_date?relativeDate(f.goal_date):'No deadline set'}</small></div><div class="overviewTrack"><div><span>Expenses planned</span><b>${money(s.planned)}</b></div><div class="progress"><span style="width:${plannedPct}%"></span></div><small>${s.planGap?`${money(s.planGap)} of the goal still needs an expense breakdown`:'The goal is fully broken down into expenses'}</small></div><div class="overviewTrack"><div><span>Group committed</span><b>${money(s.total)}</b></div><div class="progress"><span style="width:${pct}%"></span></div><small>${s.gap?`${money(s.gap)} still needs commitments`:'The group has committed enough to cover the goal'}</small></div></section><section class="actionRail"><button class="actionHero" id="newPlan">${icon('plus')}<span><b>Add an expense</b><small>Hotel, tickets, meals, transportation…</small></span></button><button class="actionSimple" id="editCommit">${icon('promise')}<span><b>My commitment</b><small>${money(mine.amount_cents)} promised · ${money(remaining)} still free</small></span></button><button class="actionSimple" id="calls">${icon('call')}<span><b>Reimbursements</b><small>${myPending?`${money(myPending)} needed from you`:'Nothing due from you'}</small></span></button></section><div class="goalColumns"><div class="stack"><section class="panel expensesPanel"><div class="panelHead"><div><span class="eyebrow">What this goal costs</span><h2>Expenses</h2></div><button class="button small secondary" id="addPlan">${icon('plus')} Add expense</button></div>${plansBlock()}</section><section class="panel"><div class="panelHead"><div><span class="eyebrow">After someone pays</span><h2>Reimbursements</h2></div></div>${callsBlock()}</section></div><div class="stack"><section class="panel"><div class="panelHead"><div><span class="eyebrow">Who has promised what</span><h2>Commitments</h2></div><span class="countPill">${state.members.length}</span></div><div class="memberList">${state.members.map(memberRow).join('')}</div></section><section class="panel"><div class="panelHead"><div><span class="eyebrow">Settlement</span><h2>Who owes whom</h2></div></div>${settlementsBlock()}</section></div></div>`;$('#app').innerHTML=shell(content);bindShell();$('#backHome').onclick=goHome;$('#invite').onclick=showInvite;$('#editGoal').onclick=showEditGoal;$('#goalSettings').onclick=showGoalSettings;$('#editCommit').onclick=showCommitment;$('#newPlan').onclick=showPlan;$('#addPlan').onclick=showPlan;$('#calls').onclick=showCallsSheet;$$('[data-plan-open]').forEach(b=>{b.onclick=()=>showExpenseDetails(b.dataset.planOpen);b.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('button')){e.preventDefault();showExpenseDetails(b.dataset.planOpen)}}});$$('[data-plan-paid]').forEach(b=>b.onclick=e=>{e.stopPropagation();showMarkPaid(b.dataset.planPaid)});$$('[data-plan-claim]').forEach(b=>b.onclick=e=>{e.stopPropagation();claimExpense(b.dataset.planClaim)});$$('[data-share-paid]').forEach(b=>b.onclick=()=>showMarkSharePaid(b.dataset.sharePaid));$$('[data-confirm-settlement]').forEach(b=>b.onclick=()=>confirmSettlement(b.dataset.confirmSettlement));$('#emptyPlan')?.addEventListener('click',showPlan)}
function strengthLabel(s){return s==='firm'?'Firm promise':s==='flexible'?'Flexible promise':'Tentative promise'}
function plansBlock(){if(!state.plans.length)return `<button class="expenseEmpty" id="emptyPlan"><span>${icon('plus')}</span><div><b>Add the first expense</b><p>Break the goal into the things the group will actually need: lodging, tickets, food, transportation, and more.</p></div></button>`;return `<div class="expenseList">${state.plans.map(p=>{const alloc=state.allocations.filter(a=>a.plan_id===p.id),mine=alloc.find(a=>a.user_id===uid()),owner=p.claimed_by?memberName(p.claimed_by):null;const coverage=p.allocation_mode==='claimed'?`${owner} is covering this`:p.allocation_mode==='split_equal'?'Split across the group':'Still needs someone to cover it';return `<article class="expenseRow ${p.status==='paid'?'done':''}" data-plan-open="${p.id}" tabindex="0"><div class="expenseStatus ${p.allocation_mode||'unassigned'}">${p.status==='paid'?icon('check'):p.allocation_mode==='claimed'?icon('promise'):icon('plan')}</div><div class="expenseBody"><div class="expenseTitle"><b>${esc(p.title)}</b><strong>${money(p.status==='paid'?(p.actual_cents||p.budget_cents):p.budget_cents)}</strong></div><small>${esc(p.category)}${p.due_date?' · '+dateOnly(p.due_date):''}</small><div class="coverageLine"><span class="coveragePill ${p.allocation_mode||'unassigned'}">${esc(coverage)}</span>${mine?.amount_cents?`<span>Your part ${money(mine.amount_cents)}</span>`:''}</div></div><div class="expenseActions">${p.status!=='paid'&&p.allocation_mode==='unassigned'?`<button class="miniButton primaryMini" data-plan-claim="${p.id}">I'll cover it</button>`:''}${p.status!=='paid'?`<button class="miniButton" data-plan-paid="${p.id}">Paid</button>`:''}</div></article>`}).join('')}</div>`}
function callsBlock(){const open=state.calls.filter(c=>c.status==='open');if(!open.length)return `<div class="emptyState compact"><span>${icon('call')}</span><b>No money is needed right now</b><p>When a planned expense is paid, Save creates reimbursement requests and shows each person's responsibility.</p></div>`;return `<div class="callList">${open.map(c=>{const mine=state.shares.find(s=>s.call_id===c.id&&s.user_id===uid());let action='—';if(mine){if(mine.status==='pending'||mine.status==='declined')action=`<button class="button small primary" data-share-paid="${mine.id}">I paid</button>`;else if(mine.status==='paid')action=`<em>${icon('clock')} Sent · awaiting confirmation</em>`;else action=`<em>${icon('check')} Confirmed</em>`}return `<article class="callRow"><div><span class="callDue">${c.due_date?relativeDate(c.due_date):'Open now'}</span><b>${esc(c.title)}</b><small>${money(c.total_cents)} group expense</small></div><div class="callMine"><span>Your share</span><strong>${money(mine?.amount_cents||0)}</strong>${action}</div></article>`}).join('')}</div>`}
function memberRow(m){const c=commitmentFor(m.user_id),alloc=allocatedFor(m.user_id),called=calledFor(m.user_id),fulfilled=fulfilledFor(m.user_id),rate=called?Math.round(fulfilled/called*100):100,remaining=Math.max(0,Number(c.amount_cents)-alloc);return `<article class="memberRow"><div class="avatar">${memberAvatar(m)}</div><div class="memberMain"><div><b>${esc(m.profiles?.display_name||'Member')}${m.user_id===uid()?' · You':''}</b><span class="strength ${c.strength}">${esc(c.strength)}</span></div><div class="memberProgress"><span style="width:${Math.min(100,Math.round(alloc/Math.max(1,Number(c.amount_cents))*100))}%"></span></div><small>${money(c.amount_cents)} committed · ${money(remaining)} free</small></div><div class="reliability"><b>${rate}%</b><span>fulfilled</span></div></article>`}
function settlementsBlock(){const active=state.settlements.filter(s=>!['confirmed','cancelled'].includes(s.status));if(!active.length)return `<div class="emptyState compact"><span>${icon('settle')}</span><b>Everyone is settled</b><p>Reimbursements appear here after someone fronts a planned expense.</p></div>`;return `<div class="settlementList">${active.slice(0,6).map(s=>{const mine=s.from_user===uid(),owed=s.to_user===uid();return `<article class="settlementRow"><div><b>${mine?'You':esc(memberName(s.from_user))} → ${owed?'you':esc(memberName(s.to_user))}</b><small>${esc(s.method||'Any payment method')} · ${esc(s.status)}</small></div><strong>${money(s.amount_cents)}</strong>${owed&&s.status==='sent'?`<button class="miniButton" data-confirm-settlement="${s.id}">Confirm</button>`:''}</article>`}).join('')}</div>`}

function showEditGoal(){const f=state.fund;modal(`<div class="sheetHead"><div><span class="eyebrow">Edit goal</span><h2>Update the plan</h2></div><button class="close" data-close>×</button></div><div class="formGrid"><label class="field full"><span>Goal name</span><input id="egName" maxlength="80" value="${esc(f.name)}"></label><label class="field tiny"><span>Icon</span><input id="egEmoji" maxlength="4" value="${esc(f.emoji||'✦')}"></label><label class="field"><span>Goal amount</span><div class="moneyInput large"><span>$</span><input id="egAmount" type="number" min="1" step=".01" value="${Number(f.goal_cents)/100}"></div></label><label class="field"><span>Goal date</span><input id="egDate" type="date" value="${esc(f.goal_date||'')}"></label><label class="field"><span>Type</span><select id="egCategory">${['Trip','Tickets','Event','Wedding','Festival','Group Gift','Other'].map(x=>`<option ${x===f.category?'selected':''}>${x}</option>`).join('')}</select></label><label class="field full"><span>Description <em>optional</em></span><textarea id="egDescription" maxlength="500" placeholder="What are you planning together?">${esc(f.description||'')}</textarea></label></div><div class="sheetActions"><button class="button secondary" data-close>Cancel</button><button class="button primary" id="saveGoalEdit">Save changes</button></div>`);$('#saveGoalEdit').onclick=async()=>{const b=$('#saveGoalEdit'),name=$('#egName').value.trim(),goal=cents($('#egAmount').value);if(!name||goal<=0)return toast('Add a goal name and amount.','error');busy(b,true,'Saving…');const {error}=await supabase.rpc('update_goal_details',{p_fund_id:f.id,p_name:name,p_emoji:$('#egEmoji').value.trim()||'✦',p_category:$('#egCategory').value,p_goal_cents:goal,p_goal_date:$('#egDate').value||null,p_description:$('#egDescription').value.trim()||null});if(error){busy(b,false);return toast(error.message,'error')}closeModal();toast('Goal updated.','success');await refreshGoal()}}
function showExpenseDetails(id){const p=state.plans.find(x=>x.id===id);if(!p)return;const alloc=state.allocations.filter(a=>a.plan_id===id),owner=p.claimed_by?memberName(p.claimed_by):null;modal(`<div class="sheetHead"><div><span class="eyebrow">Expense</span><h2>${esc(p.title)}</h2></div><button class="close" data-close>×</button></div><div class="expenseDetailAmount"><span>${p.status==='paid'?'Actual':'Estimated'}</span><strong>${money(p.status==='paid'?(p.actual_cents||p.budget_cents):p.budget_cents)}</strong><small>${esc(p.category)}${p.due_date?' · '+dateOnly(p.due_date):''}</small></div><div class="ownershipCard"><span>Coverage</span><b>${p.allocation_mode==='claimed'?`${esc(owner)} is covering this`:p.allocation_mode==='split_equal'?'Split equally with the group':'Nobody has committed to this expense yet'}</b>${alloc.length?`<div class="allocationChips">${alloc.map(a=>`<span>${esc(memberName(a.user_id))} · ${money(a.amount_cents)}</span>`).join('')}</div>`:''}</div>${p.notes?`<div class="detailNotes"><span>Notes</span><p>${esc(p.notes)}</p></div>`:''}${p.status!=='paid'?`<div class="sheetActionStack"><button class="button primary full" id="detailClaim">${p.allocation_mode==='claimed'&&p.claimed_by===uid()?'You are covering this':"I'll cover this expense"}</button><button class="button secondary full" id="detailEdit">${icon('edit')} Edit expense</button>${p.allocation_mode!=='unassigned'?`<button class="button ghost full" id="detailUnassign">Remove commitment assignment</button>`:''}<button class="button secondary full" id="detailPaid">Mark as paid</button><button class="button ghost dangerText full" id="detailRemove">Remove expense</button></div>`:''}`);$('#detailClaim')?.addEventListener('click',()=>claimExpense(id));$('#detailEdit')?.addEventListener('click',()=>showEditExpense(id));$('#detailUnassign')?.addEventListener('click',()=>unassignExpense(id));$('#detailPaid')?.addEventListener('click',()=>showMarkPaid(id));$('#detailRemove')?.addEventListener('click',()=>removeExpense(id))}
function showEditExpense(id){const p=state.plans.find(x=>x.id===id);if(!p)return;modal(`<div class="sheetHead"><div><span class="eyebrow">Edit expense</span><h2>${esc(p.title)}</h2></div><button class="close" data-close>×</button></div><label class="field"><span>Expense</span><input id="epTitle" maxlength="120" value="${esc(p.title)}"></label><div class="formGrid"><label class="field"><span>Estimated cost</span><div class="moneyInput"><span>$</span><input id="epBudget" type="number" min=".01" step=".01" value="${Number(p.budget_cents)/100}"></div></label><label class="field"><span>Needed by</span><input id="epDate" type="date" value="${esc(p.due_date||'')}"></label><label class="field"><span>Category</span><select id="epCategory">${['Lodging','Travel','Tickets','Food','Transportation','Activities','Other'].map(x=>`<option ${x===p.category?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="field"><span>Notes</span><textarea id="epNotes" maxlength="500">${esc(p.notes||'')}</textarea></label><div class="sheetActions"><button class="button secondary" data-close>Cancel</button><button class="button primary" id="saveExpenseEdit">Save expense</button></div>`);$('#saveExpenseEdit').onclick=async()=>{const b=$('#saveExpenseEdit'),title=$('#epTitle').value.trim(),budget=cents($('#epBudget').value);if(!title||budget<=0)return toast('Add a name and amount.','error');busy(b,true,'Saving…');const {error}=await supabase.rpc('update_plan_simple',{p_plan_id:id,p_title:title,p_category:$('#epCategory').value,p_budget_cents:budget,p_due_date:$('#epDate').value||null,p_notes:$('#epNotes').value.trim()||null});if(error){busy(b,false);return toast(error.message,'error')}closeModal();toast('Expense updated.','success');await refreshGoal()}}
function removeExpense(id){const p=state.plans.find(x=>x.id===id);if(!p)return;modal(`<div class="sheetHead"><div><span class="eyebrow">Remove expense</span><h2>${esc(p.title)}</h2></div><button class="close" data-close>×</button></div><p class="sheetCopy">Remove this planned expense from the goal? Its planning allocation will be cleared. This does not reverse anything paid outside Save.</p><div class="sheetActions"><button class="button secondary" data-close>Keep expense</button><button class="button danger" id="confirmRemoveExpense">Remove expense</button></div>`);$('#confirmRemoveExpense').onclick=async()=>{const b=$('#confirmRemoveExpense');busy(b,true,'Removing…');const {error}=await supabase.rpc('cancel_plan',{p_plan_id:id});if(error){busy(b,false);return toast(error.message,'error')}closeModal();const refreshed=await refreshGoal({silent:true});toast(refreshed?'Expense removed.':'Expense removed, but the view could not refresh.','success')}}
async function claimExpense(id){const {error}=await supabase.rpc('claim_plan',{p_plan_id:id});if(error)return toast(error.message,'error');closeModal();toast('You committed to covering this expense.','success');await refreshGoal()}
async function unassignExpense(id){const {error}=await supabase.rpc('unassign_plan',{p_plan_id:id});if(error)return toast(error.message,'error');closeModal();toast('Expense is now unassigned.','success');await refreshGoal()}
function showGoalSettings(){const me=state.members.find(m=>m.user_id===uid()),isOwner=me?.role==='owner'||state.fund.owner_id===uid();modal(`<div class="sheetHead"><div><span class="eyebrow">Goal settings</span><h2>${esc(state.fund.name)}</h2></div><button class="close" data-close>×</button></div>${isOwner?`<button class="settingsRow" id="settingsEditGoal">${icon('edit')}<span><b>Edit goal details</b><small>Name, target amount, date and description</small></span></button><div class="settingsDivider"></div><button class="settingsRow dangerText" id="deleteGoal">${icon('trash')}<span><b>Delete goal</b><small>Permanently remove this goal and its planning history</small></span></button>`:`<p class="sheetCopy">Only the goal owner can edit or delete this goal.</p>`}`);$('#settingsEditGoal')?.addEventListener('click',showEditGoal);$('#deleteGoal')?.addEventListener('click',showDeleteGoalConfirm)}
function showDeleteGoalConfirm(){const name=state.fund.name;modal(`<div class="sheetHead"><div><span class="eyebrow">Delete goal</span><h2>This cannot be undone</h2></div><button class="close" data-close>×</button></div><p class="sheetCopy">Delete <b>${esc(name)}</b> and all of its Save planning records? This does not move or cancel any payments outside Save.</p><label class="field"><span>Type the goal name to confirm</span><input id="deleteGoalName" autocomplete="off" placeholder="${esc(name)}"></label><div class="sheetActions"><button class="button secondary" data-close>Cancel</button><button class="button danger" id="confirmDeleteGoal" disabled>Delete permanently</button></div>`);const input=$('#deleteGoalName'),btn=$('#confirmDeleteGoal');input.oninput=()=>btn.disabled=input.value.trim()!==name;btn.onclick=async()=>{busy(btn,true,'Deleting…');const {error}=await supabase.rpc('delete_goal',{p_fund_id:state.fund.id});if(error){busy(btn,false);return toast(error.message,'error')}closeModal();toast('Goal deleted.','success');await goHome()}}
function showCreateGoal(){modal(`<div class="sheetHead"><div><span class="eyebrow">New shared goal</span><h2>What are you committing to?</h2></div><button class="close" data-close>×</button></div><div class="formGrid"><label class="field full"><span>Goal name</span><input id="gName" maxlength="80" placeholder="Miami 2027" autofocus></label><label class="field tiny"><span>Icon</span><input id="gEmoji" value="✈️" maxlength="4"></label><label class="field"><span>Target cost</span><div class="moneyInput"><span>$</span><input id="gGoal" type="number" min="1" step=".01" placeholder="6000"></div></label><label class="field"><span>Your initial commitment</span><div class="moneyInput"><span>$</span><input id="gMine" type="number" min="0" step=".01" placeholder="1000"></div><small>This is a promise, not a payment.</small></label><label class="field"><span>Goal date</span><input id="gDate" type="date"></label><label class="field"><span>Type</span><select id="gCategory"><option>Trip</option><option>Tickets</option><option>Event</option><option>Wedding</option><option>Festival</option><option>Group Gift</option><option>Other</option></select></label><label class="field full"><span>Description <em>optional</em></span><textarea id="gDescription" maxlength="500" placeholder="What are you planning together?"></textarea></label></div><div class="promiseNotice">${icon('shield')}<div><b>No money moves when you create this goal.</b><span>Members decide what they can commit and fulfill expenses outside Save.</span></div></div><div class="sheetActions"><button class="button secondary" data-close>Cancel</button><button class="button primary" id="createGoal">Create goal</button></div>`);$('#createGoal').onclick=async()=>{const b=$('#createGoal'),name=$('#gName').value.trim(),goal=cents($('#gGoal').value),mine=cents($('#gMine').value);if(!name||goal<100)return toast('Add a name and target of at least $1.','error');busy(b,true,'Creating…');const {data,error}=await supabase.rpc('create_commitment_goal',{p_name:name,p_emoji:$('#gEmoji').value.trim()||'✦',p_category:$('#gCategory').value,p_goal_cents:goal,p_goal_date:$('#gDate').value||null,p_initial_commitment_cents:mine});if(error){busy(b,false);return toast(error.message,'error')}let detailWarning=false;if($('#gDescription')?.value.trim()){const detailResult=await supabase.rpc('update_goal_details',{p_fund_id:data,p_name:name,p_emoji:$('#gEmoji').value.trim()||'✦',p_category:$('#gCategory').value,p_goal_cents:goal,p_goal_date:$('#gDate').value||null,p_description:$('#gDescription').value.trim()});detailWarning=!!detailResult.error;if(detailResult.error)console.error('Goal description update failed',detailResult.error)}closeModal();await openGoal(data);if(detailWarning)toast('Goal created, but its description could not be saved.','error')}}
function showJoin(){modal(`<div class="sheetHead"><div><span class="eyebrow">Join a goal</span><h2>Enter the invite code</h2></div><button class="close" data-close>×</button></div><label class="field"><span>Invite code</span><input id="joinCode" class="codeInput" maxlength="12" autocomplete="off" placeholder="AB12CD34" autofocus></label><p class="sheetCopy">Joining does not commit any amount automatically. You choose your own promise after joining.</p><div class="sheetActions"><button class="button secondary" data-close>Cancel</button><button class="button primary" id="joinNow">Join goal</button></div>`);$('#joinNow').onclick=async()=>{const b=$('#joinNow'),code=$('#joinCode').value.trim();if(!code)return;busy(b,true,'Joining…');const {data,error}=await supabase.rpc('join_commitment_goal',{p_code:code});if(error){busy(b,false);return toast(error.message,'error')}closeModal();await openGoal(data)}}
function showInvite(){modal(`<div class="sheetHead"><div><span class="eyebrow">Invite people</span><h2>Build the commitment together</h2></div><button class="close" data-close>×</button></div><div class="inviteCode"><span>Goal code</span><strong>${esc(state.fund.invite_code)}</strong><button class="button secondary" id="copyCode">Copy</button></div><p class="sheetCopy">Anyone with this code can join after signing in with Google. They start at $0 and choose their own commitment.</p>`);$('#copyCode').onclick=async()=>{await navigator.clipboard.writeText(state.fund.invite_code);toast('Invite code copied.','success')}}
function showCommitment(){const c=commitmentFor(uid());modal(`<div class="sheetHead"><div><span class="eyebrow">Your promise</span><h2>Set your commitment</h2></div><button class="close" data-close>×</button></div><div class="commitEditor"><label class="field"><span>Total you can commit</span><div class="moneyInput large"><span>$</span><input id="cAmount" type="number" min="0" step=".01" value="${Number(c.amount_cents)/100}"></div></label><div class="strengthPicker"><button data-strength="firm" class="${c.strength==='firm'?'active':''}"><b>Firm</b><small>I expect to cover this when called.</small></button><button data-strength="flexible" class="${c.strength==='flexible'?'active':''}"><b>Flexible</b><small>Count it, but I may need notice.</small></button><button data-strength="tentative" class="${c.strength==='tentative'?'active':''}"><b>Tentative</b><small>Useful for planning, not guaranteed.</small></button></div><hr><div class="autoCommitHead"><div><b>Build my commitment automatically</b><small>This changes only your promise. It never charges you.</small></div><label class="switch"><input id="autoToggle" type="checkbox" ${c.auto_build_cents>0?'checked':''}><span></span></label></div><div id="autoFields" class="formGrid ${c.auto_build_cents>0?'':'hidden'}"><label class="field"><span>Add</span><div class="moneyInput"><span>$</span><input id="autoAmount" type="number" min="1" step=".01" value="${c.auto_build_cents?Number(c.auto_build_cents)/100:50}"></div></label><label class="field"><span>Every</span><select id="autoCadence"><option value="weekly" ${c.auto_build_cadence==='weekly'?'selected':''}>Week</option><option value="biweekly" ${c.auto_build_cadence==='biweekly'?'selected':''}>2 weeks</option><option value="monthly" ${c.auto_build_cadence==='monthly'?'selected':''}>Month</option></select></label></div></div><div class="sheetActions"><button class="button secondary" data-close>Cancel</button><button class="button primary" id="saveCommit">Save commitment</button></div>`);let strength=c.strength;$$('[data-strength]').forEach(b=>b.onclick=()=>{$$('[data-strength]').forEach(x=>x.classList.remove('active'));b.classList.add('active');strength=b.dataset.strength});$('#autoToggle').onchange=e=>$('#autoFields').classList.toggle('hidden',!e.target.checked);$('#saveCommit').onclick=async()=>{const b=$('#saveCommit'),auto=$('#autoToggle').checked,amount=cents($('#cAmount').value),autoAmount=auto?cents($('#autoAmount').value):0,cadence=auto?$('#autoCadence').value:null;busy(b,true,'Saving…');const {error}=await supabase.rpc('set_my_commitment',{p_fund_id:state.fund.id,p_amount_cents:amount,p_strength:strength,p_auto_build_cents:autoAmount,p_auto_build_cadence:cadence});if(error){busy(b,false);return toast(error.message,'error')}const refreshed=await refreshGoal({silent:true});const saved=state.commitments.find(x=>x.user_id===uid());if(!refreshed||!saved||Number(saved.amount_cents)!==amount){busy(b,false);console.error('Commitment write succeeded but verification failed',{expected:amount,saved});return toast('Commitment saved, but Save could not verify the updated view. Refresh and try again if it does not appear.','error')}closeModal();toast('Commitment updated. No money moved.','success')}}
function showPlan(){modal(`<div class="sheetHead"><div><span class="eyebrow">Add to the goal</span><h2>Add an expense</h2></div><button class="close" data-close>×</button></div><label class="field"><span>What will the group need?</span><input id="pTitle" maxlength="120" placeholder="Hotel, concert tickets, rental car…" autofocus></label><div class="formGrid"><label class="field"><span>Estimated cost</span><div class="moneyInput large"><span>$</span><input id="pBudget" type="number" min=".01" step=".01" placeholder="400"></div></label><label class="field"><span>Needed by</span><input id="pDate" type="date"></label><label class="field"><span>Category</span><select id="pCategory"><option>Lodging</option><option>Travel</option><option>Tickets</option><option>Food</option><option>Transportation</option><option>Activities</option><option>Other</option></select></label></div><div class="choiceLabel"><b>Who is committing to this expense?</b><small>You can change this later.</small></div><div class="coverageChoices"><button class="coverageChoice active" data-mode="unassigned"><span class="choiceIcon">${icon('plan')}</span><div><b>Just add it</b><small>Show that the group needs this expense. Nobody is committed to covering it yet.</small></div></button><button class="coverageChoice" data-mode="claimed"><span class="choiceIcon">${icon('promise')}</span><div><b>I'll cover it</b><small>Reserve the full amount from my commitment. Save will increase my commitment if needed.</small></div></button><button class="coverageChoice" data-mode="split_equal"><span class="choiceIcon">${icon('users')}</span><div><b>Split with the group</b><small>Reserve an equal share against each member's commitment.</small></div></button></div><label class="field"><span>Notes <em>optional</em></span><textarea id="pNotes" maxlength="500" placeholder="Reservation details, seat section, what this includes…"></textarea></label><div class="sheetActions"><button class="button secondary" data-close>Cancel</button><button class="button primary" id="createPlan">Add expense</button></div>`);let mode='unassigned';$$('[data-mode]').forEach(b=>b.onclick=()=>{$$('[data-mode]').forEach(x=>x.classList.remove('active'));b.classList.add('active');mode=b.dataset.mode});$('#createPlan').onclick=async()=>{const b=$('#createPlan'),title=$('#pTitle').value.trim(),budget=cents($('#pBudget').value);if(!title||budget<=0)return toast('Add an expense name and estimated cost.','error');busy(b,true,'Adding…');const {error}=await supabase.rpc('create_plan_simple',{p_fund_id:state.fund.id,p_title:title,p_category:$('#pCategory').value,p_budget_cents:budget,p_due_date:$('#pDate').value||null,p_notes:$('#pNotes').value.trim()||null,p_coverage_mode:mode});if(error){busy(b,false);return toast(error.message,'error')}closeModal();toast(mode==='claimed'?'Expense added and added to your commitment.':'Expense added to the goal.','success');await refreshGoal()}}
function showMarkPaid(planId){const p=state.plans.find(x=>x.id===planId);modal(`<div class="sheetHead"><div><span class="eyebrow">Expense happened</span><h2>Who fronted ${esc(p.title)}?</h2></div><button class="close" data-close>×</button></div><div class="formGrid"><label class="field"><span>Actual total</span><div class="moneyInput"><span>$</span><input id="actual" type="number" min=".01" step=".01" value="${Number(p.budget_cents)/100}"></div></label><label class="field"><span>Paid by</span><select id="payer">${state.members.map(m=>`<option value="${m.user_id}" ${m.user_id===uid()?'selected':''}>${esc(m.profiles?.display_name||'Member')}</option>`).join('')}</select></label></div><div class="promiseNotice">${icon('call')}<div><b>This creates a reimbursement request.</b><span>${p.allocation_mode==='unassigned'?"This expense was not assigned, so the actual total will be split equally across active members.":"The payer's share is marked covered; everyone else's proportional share becomes a reimbursement obligation."}</span></div></div><div class="sheetActions"><button class="button secondary" data-close>Cancel</button><button class="button primary" id="markPaid">Create reimbursement request</button></div>`);$('#markPaid').onclick=async()=>{const b=$('#markPaid'),actual=cents($('#actual').value);busy(b,true,'Creating request…');const {error}=await supabase.rpc('mark_plan_paid',{p_plan_id:planId,p_actual_cents:actual,p_paid_by:$('#payer').value});if(error){busy(b,false);return toast(error.message,'error')}closeModal();toast('Reimbursement request created.','success');await refreshGoal()}}
function showMarkSharePaid(id){const s=state.shares.find(x=>x.id===id),call=state.calls.find(c=>c.id===s.call_id);modal(`<div class="sheetHead"><div><span class="eyebrow">Record fulfillment</span><h2>I paid ${money(s.amount_cents)}</h2></div><button class="close" data-close>×</button></div><p class="sheetCopy">Save does not send this payment. Pay ${esc(memberName(s.paid_by))} outside Save using whatever method you agree on, then record it here.</p><label class="field"><span>How did you pay?</span><select id="method"><option>Venmo</option><option>Zelle</option><option>PayPal</option><option>Apple Cash</option><option>Cash</option><option>Bank transfer</option><option>Other</option></select></label><label class="field"><span>Note (optional)</span><input id="payNote" maxlength="200" placeholder="Sent just now"></label><div class="sheetActions"><button class="button secondary" data-close>Cancel</button><button class="button primary" id="recordPaid">Mark as sent</button></div>`);$('#recordPaid').onclick=async()=>{const b=$('#recordPaid');busy(b,true,'Recording…');const {error}=await supabase.rpc('mark_my_call_share_paid',{p_share_id:id,p_method:$('#method').value,p_note:$('#payNote').value.trim()||null});if(error){busy(b,false);return toast(error.message,'error')}closeModal();toast('Recorded as paid.','success');await refreshGoal()}}
async function confirmSettlement(id){const {error}=await supabase.rpc('confirm_settlement',{p_settlement_id:id});if(error)return toast(error.message,'error');toast('Payment confirmed.','success');await refreshGoal()}
function showCallsSheet(){const open=state.calls.filter(c=>c.status==='open');const shareLabel=s=>s.status==='covered'?'confirmed':s.status==='paid'?'sent':s.status;modal(`<div class="sheetHead"><div><span class="eyebrow">Money needed now</span><h2>Reimbursement requests</h2></div><button class="close" data-close>×</button></div>${open.length?open.map(c=>{const ss=state.shares.filter(s=>s.call_id===c.id);return `<section class="detailGroup"><div class="detailTitle"><div><b>${esc(c.title)}</b><small>${money(c.total_cents)} · ${c.due_date?dateOnly(c.due_date):'Open'}</small></div><span>${ss.filter(s=>s.status==='covered').length}/${ss.length} confirmed</span></div>${ss.map(s=>`<div class="detailRow"><span>${esc(memberName(s.user_id))}</span><b>${money(s.amount_cents)}</b><em class="${s.status}">${esc(shareLabel(s))}</em></div>`).join('')}</section>`}).join(''):'<div class="emptyState"><b>No open reimbursement requests</b><p>The group has nothing to reimburse right now.</p></div>'}`,true)}
function showSettlementsSheet(){modal(`<div class="sheetHead"><div><span class="eyebrow">Clear obligations</span><h2>Settlement ledger</h2></div><button class="close" data-close>×</button></div>${state.settlements.length?state.settlements.map(s=>`<div class="detailRow settlementDetail"><span>${esc(memberName(s.from_user))} → ${esc(memberName(s.to_user))}</span><b>${money(s.amount_cents)}</b><em class="${s.status}">${esc(s.status)}</em></div>`).join(''):'<div class="emptyState"><b>Nothing to settle</b><p>Once someone fronts a shared expense, obligations appear here.</p></div>'}`,true)}
function showHow(){const content=`<section class="howHero"><span class="eyebrow">The Save model</span><h1>Commitment before collection.</h1><p>Save is a coordination layer for shared spending. It does not hold deposits, issue cards, or move funds.</p></section><section class="howGrid"><article><span>${icon('target')}</span><b>1. Set a goal</b><p>Define the trip, tickets, event, or group purchase and its expected total cost.</p></article><article><span>${icon('promise')}</span><b>2. Make commitments</b><p>Each person promises what they can contribute, with firm, flexible, or tentative confidence.</p></article><article><span>${icon('plan')}</span><b>3. Reserve plans</b><p>Expected expenses earmark portions of those promises before anyone purchases anything.</p></article><article><span>${icon('call')}</span><b>4. Request when needed</b><p>When someone fronts an actual expense, Save calculates each person's responsibility.</p></article><article><span>${icon('settle')}</span><b>5. Settle outside Save</b><p>Members reimburse through their preferred payment method and record/confirm fulfillment.</p></article><article><span>${icon('repeat')}</span><b>Auto Commit</b><p>Optionally increase your promise on a schedule—behavioral saving without automatic charges.</p></article></section>`;$('#app').innerHTML=shell(content,'how');bindShell()}
function showAccount(){modal(`<div class="sheetHead"><div><span class="eyebrow">Account</span><h2>${esc(state.profile?.display_name||'Saver')}</h2></div><button class="close" data-close>×</button></div><div class="accountSummary">${state.profile?.avatar_url?`<img src="${esc(state.profile.avatar_url)}" alt="">`:`<span>${esc((state.profile?.display_name||'S')[0])}</span>`}<div><b>Google account</b><small>${esc(state.session.user.email||'')}</small></div></div><div class="promiseNotice">${icon('shield')}<div><b>Save does not connect to your bank.</b><span>Your commitments are planning records, not verified account balances.</span></div></div><button class="button danger full" id="signOut">Sign out</button>`);$('#signOut').onclick=async()=>{await supabase.auth.signOut();closeModal()}}

async function refreshGoal(options={}){if(!state.fund)return false;const id=state.fund.id;try{const qs=await Promise.all([
 supabase.from('funds').select('*').eq('id',id).single(),
 supabase.from('fund_members').select('*,profiles(display_name,avatar_url)').eq('fund_id',id).eq('status','active').order('joined_at'),
 supabase.from('commitments').select('*').eq('fund_id',id).neq('status','cancelled'),
 supabase.from('planned_expenses').select('*').eq('fund_id',id).neq('status','cancelled').order('due_date',{ascending:true,nullsFirst:false}),
 supabase.from('plan_allocations').select('*').eq('fund_id',id),
 supabase.from('funding_calls').select('*').eq('fund_id',id).neq('status','cancelled').order('created_at',{ascending:false}),
 supabase.from('funding_call_shares').select('*').eq('fund_id',id),
 supabase.from('settlements').select('*').eq('fund_id',id).order('created_at',{ascending:false}),
 supabase.from('commitment_events').select('*').eq('fund_id',id).order('created_at',{ascending:false}).limit(30)
]);const failed=qs.map((q,i)=>q.error?{index:i,error:q.error}:null).filter(Boolean);if(failed.length){console.error('Save refresh failed',failed);if(!options.silent)toast('Save could not refresh all goal data. Try again.','error');return false;}[state.fund,state.members,state.commitments,state.plans,state.allocations,state.calls,state.shares,state.settlements,state.events]=qs.map(q=>q.data);renderGoal();return true}catch(error){console.error('Save refresh failed',error);if(!options.silent)toast(error.message||'Save could not refresh this goal.','error');return false}}
function subscribe(id){unsubscribe();const tables=['commitments','planned_expenses','plan_allocations','funding_calls','funding_call_shares','settlements','fund_members'];let ch=supabase.channel(`save-commit-${id}`);for(const table of tables)ch=ch.on('postgres_changes',{event:'*',schema:'public',table,filter:`fund_id=eq.${id}`},scheduleRefresh);ch=ch.on('postgres_changes',{event:'UPDATE',schema:'public',table:'funds',filter:`id=eq.${id}`},scheduleRefresh);state.channel=ch.subscribe(status=>{if(status==='CHANNEL_ERROR'||status==='TIMED_OUT')console.warn('Save realtime unavailable; manual refresh remains available.',status)})}
function scheduleRefresh(){clearTimeout(state.refreshTimer);state.refreshTimer=setTimeout(()=>refreshGoal(),180)}
function unsubscribe(){clearTimeout(state.refreshTimer);if(state.channel){supabase.removeChannel(state.channel);state.channel=null}}

init();
